/*
 * Modified by Actuna Sp. z o.o.:
 *   E-01: deploy pipeline - one internal function for every deployment; the lock
 *   is held until the start completes (R-43)
 *   P-01: deployOpts.waitForStart (deploy.response "started") documented
 *   Z-04: checkRevision() shared by the whole-configuration and single-flow api
 *   Z-05: deploy.requireRevision - 409 version_required (also for the v1 api)
 *   E-02: instance state "deploying" in step 4 and the result of the start in step 8
 *   Z-09: reload from storage (source "storage", contract part B) - reread under
 *   the lock, instance state "reloading", no save
 *   #1 (R-47): a successful deployment clears the condition `reload` of the
 *   instance state (a failed reload from storage)
 *   Z-06 (#10): the preDeploy and postDeploy hooks (flows/deployHooks.js). `opts.prepare` - the single-flow
 *   api checks the revisions and builds the configuration in step 2 (before step 4), so a rejected request no
 *   longer passes through the state "deploying"; its result goes to `apply`. Reload: step 2 only reads storage
 *   (readStoredFlows), the credentials and the runtime-state event are step 3a, after the hook and before
 *   "deploying" (D15). Step 3 runs the preDeploy handlers (without a handler nothing is copied and no timer
 *   is set). Step 11: postDeploy once for every saved or reloaded configuration (the fact "saved" is the
 *   replacement of the active configuration, read under the lock; for a reload from storage after
 *   begin("reload") - D22/A31), with the dictionary of `start.status` (deployHooks.classifyStart); the handlers
 *   run after the result, asynchronously. The deployment type "load" (header Node-RED-Deployment-Type, deploys
 *   the content of storage and ignores the body) is validated on the content of storage when a preDeploy
 *   handler is registered, like "reload"
 *   #63: comment of the moment the preDeploy handlers are read (only whether one is registered, before step 2)
 *   #84: an instance that is stopping (state stopping/stopped) refuses every deployment with 503 runtime_stopping
 *   (stoppingError()) before the lock is waited for, first under the lock, after step 3 and at step 4; a reload
 *   from storage whose begin("reload") is refused returns {skipped: "stopping"}; postDeploy start.status
 *   "not_started" when the stop began before the deployment returned; a reload from storage that takes the
 *   lock while the instance is stopping returns {skipped: "stopping"} (not "superseded")
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The deploy pipeline (contract E-01, design/engine-extensions/ZASADY.md §2.3 A).
 *
 * Every deployment that enters the runtime - `POST /flows` (full, nodes, flows,
 * reload) and the single-flow api (`POST /flow`, `PUT`/`DELETE /flow/:id`) -
 * goes through `deploy(opts)`, so later packages add their steps in one place.
 * Steps (numbers as in the contract):
 *
 *   1  request accepted (opts.source: "api" | "internal" | "storage"); refused (503
 *      runtime_stopping, #84) when the instance is stopping - also before the lock is waited for
 *   -- deploy lock (flows/lock.js) --
 *      #84: refused first under the lock, before step 2, when the instance is stopping
 *   2  revision check (409 version_mismatch); single-flow api: `prepare` (revisions
 *      and the new configuration, Z-06); reload: read storage here (only read - no
 *      side effects, Z-06 D15), under the lock and before step 3 (R-11)
 *   2a node type permissions - anchor (Z-12.08)
 *   3  preDeploy hook (Z-06, flows/deployHooks.js): a registered handler can reject the
 *      deployment (400 deploy_rejected) or stop it (503 deploy_hook_failed / deploy_hook_timeout)
 *      #84: refused after step 3, before step 3a, when the instance is stopping
 *   3a reload: load the credentials of the configuration read in step 2 and publish
 *      the runtime state (Z-06 D15) - after the hook, before step 4
 *   4  state "deploying" - anchor (E-02 / Z-08); #84: `begin()` refused (null) in stopping - the
 *      deployment is refused, nothing is saved
 *   5  save to storage (reload: nothing saved)        - flows.setFlows / apply
 *   6  stop changed nodes (default: errors swallowed, D-05)
 *   7  start new nodes (asynchronously, as in 5.0.7); flows.setFlows registers
 *      the start with lock.holdUntil()
 *  10  result returned - after step 6, before the start completes (unless
 *      deployOpts.waitForStart, P-01); the lock is still held
 *   8  state "ready"/"failed" - when the start completes - anchor (E-02 / Z-08)
 *   -- end of lock: when the start completes, also if it fails (R-43) --
 *   9  runtime-deploy event - emitted by flows.setFlows when the start completes
 *  11  postDeploy hook (Z-06, flows/deployHooks.js): the facts are collected under the lock,
 *      the handlers run after the result is returned (setImmediate), in parallel, never delay
 *      the response or the next deployment, and only for a configuration that was saved (or
 *      reloaded from storage) - also when the deployment then ended with an error
 *
 * A reload after a change in storage (Z-09, contract part B, flows/reload.js)
 * uses `deploy({type: "reload", source: "storage", reread})`: under the lock
 * `reread()` reads storage again and decides; the reload is applied with
 * `flows.reloadFromStorage()` in the instance state "reloading" - no preDeploy,
 * nothing saved, postDeploy (source "storage") once the reload was applied. It is skipped
 * when a deployment superseded the pending reload, and (#84) when the instance started to stop
 * before the state "reloading" (`{skipped: "stopping"}`).
 *
 * `POST /flows/state` and project switches use the same lock (flows/lock.js)
 * but not this function: they have no steps 2-5 and no hooks (R-11, R-15).
 * @module
 */

const lock = require("./lock");
const instanceState = require("../state");
const deployHooks = require("./deployHooks");
const hooks = require("@node-red/util").hooks;

let runtime;

/**
 * @typedef DeployOpts
 * @type {object}
 * @property {boolean} [waitForStart=false] - resolve after the new flows have
 *     started (P-01, `deploy.response: "started"`); set by the runtime api, the
 *     result then comes after steps 7-9 (or the error deploy_start_failed /
 *     deploy_stop_failed with `rev`)
 */

function init(_runtime) {
    runtime = _runtime;
    deployHooks.init(_runtime);
}

/**
 * #84 (D2, D7): the refusal of a change while the instance is stopping (state stopping or
 * stopped): `{code: "runtime_stopping", status: 503, message}` - a constant catalogue text,
 * nothing of the request. Nothing was changed: the change can be made again after the restart
 * or on another instance. Also used by `POST /flows/state` (api/flows.js).
 * @return {Error}
 */
function stoppingError() {
    const err = new Error(runtime.log._("api.flows.runtime-stopping"));
    err.code = "runtime_stopping";
    err.status = 503;
    return err;
}

function revisionError(code, status, message) {
    const err = new Error(message);
    err.code = code;
    err.status = status;
    return err;
}

/**
 * Checks a revision given with a deployment (contract E-01 step 2; Z-04).
 * `null` as the current revision means that the target does not exist yet: a given
 * `null` then matches ("create only if it does not exist").
 * @param {Object} opts
 * @param {boolean} opts.present - whether the request contains the revision
 * @param {*} opts.value - the given revision
 * @param {String|null} opts.current - the current revision
 * @param {boolean} [opts.strictType] - a revision that is not a string (or null) is
 *     rejected with 400 `invalid_revision` instead of 409 `version_mismatch`
 * @param {boolean} [opts.required] - a revision is required (Z-05, `deploy.requireRevision`):
 *     a missing or empty revision (`""` or `null` - N-01) is rejected with 409
 *     `version_required`; `null` is accepted when the target does not exist
 *     (`opts.current === null`, creating a flow). Implies `strictType`
 * @param {String} [opts.message] - the message of the `version_required` error
 * @throws {Error} 409 `version_mismatch`, 409 `version_required`, 400 `invalid_revision`
 */
function checkRevision(opts) {
    if (opts.required) {
        if (!opts.present || opts.value === undefined || opts.value === "" || (opts.value === null && opts.current !== null)) {
            throw revisionError("version_required", 409, opts.message || "A revision is required");
        }
    }
    if (!opts.present) {
        return;
    }
    if ((opts.strictType || opts.required) && opts.value !== null && typeof opts.value !== "string") {
        throw revisionError("invalid_revision", 400, "Invalid revision");
    }
    if (opts.value !== opts.current) {
        throw revisionError("version_mismatch", 409);
    }
}

function checkFlowsRevision(flows, opts) {
    const present = !!flows && flows.hasOwnProperty('rev');
    if (opts.requireRevision && opts.apiVersion === "v1") {
        // Z-05 (R-14): the v1 api has no place for a revision
        throw revisionError("version_required", 409, runtime.log._("api.flows.version-required-v1"));
    }
    checkRevision({
        present: present,
        value: flows && flows.rev,
        current: present || opts.requireRevision ? (runtime.flows.getFlows() || {}).rev : undefined,
        required: !!opts.requireRevision,
        message: opts.requireRevision ? runtime.log._("api.flows.version-required") : undefined
    });
}

/**
 * Deploys a flow configuration through the deploy pipeline.
 *
 * @param {Object} opts
 * @param {String} [opts.type="full"] - "full" | "nodes" | "flows" | "reload" | "load" (deploys the content of
 *     storage, ignores `opts.flows`; with a preDeploy handler it is read in step 2 and validated, like reload)
 * @param {String} [opts.source] - "api" | "internal" | "storage"
 * @param {Object} [opts.flows] - for full/nodes/flows: `{flows: [..], credentials: {}, rev?}`
 * @param {Function} [opts.prepare] - for the single-flow api, step 2 (Z-06, #10): checks the
 *     revisions and builds the new configuration from the active one, without side effects
 *     other than naming the input (a new flow gets its `id`); an error (404, 409, 400 ...)
 *     rejects the deployment before step 4 - the instance state is not touched. Its result
 *     is passed to `apply`
 * @param {Function} [opts.apply] - for the single-flow api: deploys the configuration
 *     (steps 5-8), called with `(deployOpts, prepared)`; its result is returned as `result`.
 *     Without `prepare` it also checks the revisions and builds, as before
 * @param {Object} [opts.loaded] - for reload: the configuration already read from
 *     storage **with its credentials loaded** (the result of `flows.readFlowsFromStorage()`:
 *     `{flows, rev, credentials}`), deployed without reading storage again and without
 *     step 3a. No caller passes it today; it is kept (an existing, tested option) because
 *     removing it would change the contract of `deploy()` without a reason
 * @param {Function} [opts.reread] - with source "storage" (Z-09): reads storage
 *     again under the lock and decides about the reload (see reloadFromStorage)
 * @param {User} [opts.user] - the user calling the api
 * @param {Object} [opts.req] - the request (optional)
 * @param {String} [opts.operation] - for the preDeploy event: "setFlows" | "addFlow" |
 *     "updateFlow" | "deleteFlow" (Z-06)
 * @param {Function} [opts.describe] - for the preDeploy event of the single-flow api: called
 *     with the result of `prepare`, returns `{flowId, created?}` (Z-06)
 * @param {boolean} [opts.requireRevision] - full/nodes/flows: a revision is required (Z-05)
 * @param {String} [opts.apiVersion] - "v1" | "v2": with requireRevision a v1 deployment
 *     is rejected with 409 version_required (R-14)
 * @param {DeployOpts} [opts.deployOpts] - internal deploy options; omitted for the
 *     default behaviour
 * @return {Promise<{rev: String}|{result: any}>} - the new revision, or the result of `apply`
 */
async function deploy(opts) {
    opts = opts || {};
    const type = opts.type || "full";
    // Step 11 (Z-06): the facts of the deployment, collected under the lock (null: no postDeploy)
    const post = { facts: null };
    if (opts.source === "storage" && typeof opts.reread === "function") {
        let reloaded;
        try {
            reloaded = await lock.runExclusive(function() { return reloadFromStorage(opts, post) });
        } catch (err) {
            if (post.facts) {
                deployHooks.notifyPostDeploy(post.facts);
            }
            throw err;
        }
        if (post.facts) {
            deployHooks.notifyPostDeploy(post.facts);
        }
        return reloaded;
    }
    // #84 (S-1, D8): an instance that is stopping changes nothing - refused before the lock
    // is waited for (a long start may hold it) and before anything of the request is read
    if (instanceState.isStopping()) {
        throw stoppingError();
    }
    let result;
    try {
        result = await lock.runExclusive(async function() {
            // #84: the instance may have started to stop while the deployment waited for the lock;
            // the refusal comes before the checks of step 2 (D8)
            if (instanceState.isStopping()) {
                throw stoppingError();
            }
            // Step 2: revision check, or - for reload - read the configuration
            // that will be deployed (under the lock, before preDeploy - R-11)
            let loaded = opts.loaded;
            let prepared;
            // One answer for the whole deployment: is there a preDeploy handler. The deployment type
            // "load" (the Admin API takes it from the header) ignores the body and deploys the content
            // of storage - with a handler it is validated on that content, exactly like "reload":
            // what the hook sees is what is deployed (I10). Without a handler it takes the old path.
            // It is read once per deployment, under the lock, before step 2: without a handler the deployment
            // takes the old path also when a handler is added meanwhile. The list of the handlers is taken by
            // step 3 when it runs: a handler added before step 3 is called, a removed one is not (#63).
            const hasPreDeploy = hooks.has("preDeploy");
            const fromStorage = type === "reload" || (type === "load" && hasPreDeploy);
            if (type === "reload") {
                if (!loaded) {
                    // D15: only reads storage; the credentials follow in step 3a
                    loaded = await runtime.flows.readStoredFlows();
                }
            } else if (opts.prepare) {
                // Z-06 (U1): the single-flow api - revisions and the new configuration
                prepared = await opts.prepare();
            } else if (!opts.apply) {
                checkFlowsRevision(opts.flows, opts);
                if (fromStorage && !loaded) {
                    // type "load" with a handler: read storage here (D15), as for reload
                    loaded = await runtime.flows.readStoredFlows();
                }
            }
            // Step 2a anchor: node type permissions (Z-12.08, R-27)
            // Step 3: preDeploy hook (Z-06, R-15) - the resulting configuration, nothing has
            // changed yet; a rejection, a failure or a timeout ends the deployment here
            if (hasPreDeploy) {
                const candidate = fromStorage ? (loaded && loaded.flows) : prepared ? prepared.config : (opts.flows && opts.flows.flows);
                // a configuration that is not an array (a malformed body) is not given to the hook:
                // the deployment fails in step 5 as in 5.0.7
                if (Array.isArray(candidate)) {
                    const info = {
                        type: type,
                        source: opts.req ? "api" : "internal",
                        operation: opts.operation,
                        flows: candidate,
                        activeRev: (runtime.flows.getFlows() || {}).rev,
                        user: opts.user
                    };
                    if (fromStorage) {
                        info.rev = loaded.rev;
                    }
                    if (prepared && opts.describe) {
                        Object.assign(info, opts.describe(prepared));
                    }
                    await deployHooks.runPreDeploy(info);
                }
            }
            // #84: the instance started to stop during step 2 or 3 (for example a preDeploy
            // handler): refused before the credentials of a reload are loaded
            if (instanceState.isStopping()) {
                throw stoppingError();
            }
            // Step 3a (D15): reload - the credentials of the configuration read in step 2
            // are loaded and the runtime state is published only now, after the hook: a
            // rejected reload changes nothing. An error (credentials_load_failed with
            // projects) comes before the state "deploying", as before.
            if (fromStorage && !opts.loaded) {
                loaded = await runtime.flows.loadStoredCredentials(loaded);
            }
            // Step 4: state "deploying" (E-02, Z-08) - before the first node is
            // stopped. A deployment from "reloadPending" cancels the pending reload.
            // The lock makes the operation exclusive; supersede covers the case of
            // deploy.startTimeoutReleasesLock (R-45), where the lock is released
            // while the start of the previous deployment still runs.
            const token = instanceState.begin("deploy", { supersede: true });
            if (token === null) {
                // #84: the instance started to stop during step 3a - nothing is saved
                throw stoppingError();
            }
            // Step 11 (Z-06): the fact "saved" is the replacement of the active configuration:
            // read it now, under the lock, and only when a postDeploy handler exists
            const track = hooks.has("postDeploy");
            const before = track ? runtime.flows.getFlows() : undefined;

            // Steps 5-8 (and 9, emitted by flows.setFlows)
            let deployed;
            try {
                if (type === "reload") {
                    deployed = { rev: await runtime.flows.loadFlows(true, opts.deployOpts, loaded) };
                } else if (opts.apply) {
                    deployed = { result: await opts.apply(opts.deployOpts, prepared) };
                } else {
                    const flows = opts.flows || {};
                    if (fromStorage) {
                        // type "load" with a handler: the same object that the hook saw is deployed (I10)
                        deployed = { rev: await runtime.flows.setFlows(flows.flows, flows.credentials, type, null, null, opts.user, opts.deployOpts, loaded) };
                    } else {
                        deployed = { rev: await runtime.flows.setFlows(flows.flows, flows.credentials, type, null, null, opts.user, opts.deployOpts) };
                    }
                }
            } catch (err) {
                if (track) {
                    // an error after the save is also a deployed configuration (D18)
                    post.facts = postFacts(opts, type, prepared, before, err, !opts.apply);
                }
                endWithStart(token, err);
                throw err;
            }
            // R-47: the configuration was saved to (or read from) storage - a failed
            // reload from storage is over, also when the start of the flows fails
            instanceState.clearReloadFailed();
            if (track) {
                post.facts = postFacts(opts, type, prepared, before, null, !opts.apply);
            }
            // Step 7 runs asynchronously: flows.setFlows registered the start with
            // lock.holdUntil(), so the lock is released when the start completes
            // (or fails) while the result is returned now (R-43).
            // Step 8: state "ready"/"failed"/"idle" (E-02, Z-08) - when the start completes
            endWithStart(token);
            return deployed;
        });
    } catch (err) {
        if (post.facts) {
            deployHooks.notifyPostDeploy(post.facts);
        }
        throw err;
    }
    // Step 11: postDeploy - asynchronously (setImmediate), does not delay the result (Z-06)
    if (post.facts) {
        deployHooks.notifyPostDeploy(post.facts);
    }
    return result;
}

/**
 * Contract part B, steps 4-5 (Z-09), under the deploy lock: reads storage again
 * through `opts.reread()` and reloads the configuration it returns.
 * @param {Object} opts
 * @param {Function} opts.reread - resolves `{apply: loaded, reloadType, credentialsChanged}`
 *     to reload, anything else to skip (the caller restores the instance state)
 * @param {Object} post - receives `facts` for the postDeploy hook (Z-06): only when the reload
 *     reached the state "reloading" and replaced the active configuration - the fact is read
 *     here, under the lock, after `begin("reload")` (D22/A31): a reload superseded by a deployment
 *     of this instance, a skipped one and a round of D-17 without a decision have no postDeploy
 * @return {Promise<{rev: String}|{skipped: any}>} - `{skipped: "stopping"}` (#84): the instance
 *     started to stop before the state "reloading" (also before the lock was taken) - nothing was reloaded
 */
async function reloadFromStorage(opts, post) {
    // #84 (B3): the instance started to stop before the reload took the lock - not "superseded",
    // so flows/reload.js ends the cycle quietly and schedules no further one
    if (instanceState.isStopping()) {
        return { skipped: "stopping" };
    }
    // A deployment on this instance superseded the pending reload (E-02 T5)
    if (instanceState.get().state !== "reloadPending") {
        return { skipped: "superseded" };
    }
    const decision = await opts.reread();
    if (!decision || !decision.apply) {
        return { skipped: decision };
    }
    // T8: "reloading" - no preDeploy (R-15), nothing saved (step 5 of part A skipped)
    const token = instanceState.begin("reload");
    if (token === null) {
        // #84 (S-2): the instance started to stop while storage was read again - nothing is
        // reloaded and there is no postDeploy; flows/reload.js ends the cycle quietly
        return { skipped: "stopping" };
    }
    const track = !!post && hooks.has("postDeploy");
    const before = track ? runtime.flows.getFlows() : undefined;
    let rev;
    try {
        rev = await runtime.flows.reloadFromStorage(decision.apply, {
            type: decision.reloadType,
            credentialsChanged: !!decision.credentialsChanged
        });
    } catch (err) {
        if (track) {
            post.facts = postFacts({ source: "storage" }, "reload", undefined, before, err, true, decision.reloadType);
        }
        endWithStart(token, err);
        throw err;
    }
    if (track) {
        post.facts = postFacts({ source: "storage" }, "reload", undefined, before, null, true, decision.reloadType);
    }
    endWithStart(token);
    return { rev: rev };
}

/**
 * The facts of a deployment for the postDeploy hook (step 11, Z-06), collected under the lock.
 * Returns null when nothing was saved or reloaded: the fact is the replacement of the active
 * configuration since `before` (`flows.getFlows()` returns the object that is replaced exactly
 * once, after the write or the read - D18), not a list of error codes. Must be called before
 * `endWithStart`, which hands the held start over to the instance state.
 * @param {Object} opts - the options of the deployment (source, req, operation, describe, user,
 *     deployOpts)
 * @param {String} type
 * @param {Object} [prepared] - the result of `prepare`
 * @param {Object} before - the active configuration before step 5
 * @param {Error} [err] - the error of steps 5-8
 * @param {boolean} direct - the error comes from `flows.setFlows`/`loadFlows` itself (not from an
 *     `apply` step that also does other work): see deployHooks.classifyStart
 * @param {String} [reloadType] - the type of a reload from storage ("full" | "diff")
 * @return {Object|null}
 */
function postFacts(opts, type, prepared, before, err, direct, reloadType) {
    const after = runtime.flows.getFlows();
    if (after === before || after === null || after === undefined) {
        return null;
    }
    const facts = {
        rev: after.rev,
        type: type,
        source: opts.source === "storage" ? "storage" : (opts.req ? "api" : "internal"),
        operation: opts.operation || null,
        flowId: null,
        user: opts.user
    };
    if (prepared && opts.describe) {
        const described = opts.describe(prepared);
        if (described && described.flowId !== undefined) {
            facts.flowId = described.flowId;
        }
    }
    if (type === "reload") {
        facts.reloadType = reloadType || "full";
    }
    const waitForStart = !!(opts.deployOpts && opts.deployOpts.waitForStart);
    // #84 (N-2): in the default mode, when the instance started to stop before the deployment
    // returned, the start is or will be skipped - "not_started", not "pending"
    const held = lock.sectionHeld().length > 0 && (waitForStart || !instanceState.isStopping());
    return Object.assign(facts, deployHooks.classifyStart(err, { waitForStart: waitForStart, held: held, direct: direct }));
}

/**
 * Step 8 (E-02): ends the "deploy" operation of the instance state with the
 * result of the start of the flows. The start registered by flows.setFlows
 * with lock.holdUntil() is chained and the chained promise is held with the
 * same options, so the state is set before the lock is released.
 * Without a start the flows were not running ("idle"); an error before the
 * start returns to the state before the deployment, except a failed stop.
 * @param {symbol|null} token
 * @param {Error} [err] - the error of steps 5-7
 */
function endWithStart(token, err) {
    const held = lock.sectionHeld();
    if (held.length > 0) {
        held.forEach(function(entry) {
            lock.holdUntil(Promise.resolve(entry.promise).then(function(result) {
                instanceState.end(token, result || { errors: [] });
            }, function(startErr) {
                instanceState.end(token, { errors: [{ code: "flow_start_failed", message: (startErr && startErr.message) || String(startErr) }] });
            }), entry.options);
        });
        return;
    }
    if (err) {
        if (err.code === "deploy_stop_failed") {
            instanceState.end(token, { errors: [{ code: "deploy_stop_failed", message: err.message }] });
        } else {
            // The configuration was not deployed: the running flows are unchanged
            instanceState.end(token, { aborted: true });
        }
        return;
    }
    instanceState.end(token, { flowsRunning: false });
}

module.exports = {
    init,
    deploy,
    checkRevision,
    stoppingError
};
